package v1

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"log"
	"net/http"
	"uopenbox/common/unigate"

	"github.com/gin-gonic/gin"
)

func Emv(g *gin.Context) {
	customerTransactionID := gorderId() //order id
	// transactionType := unigate.TxnTypeAuthorize //预授权交易
	amount := 100.00 //金额
	ctx := context.Background()
	arqc := ""

	client := unigate.NewClient("", "EF09625335", "MAG888811829", "86keSz-CrA2EDMegaD_4")

	// 授权交易
	resp, err := client.EMVAuthorize(ctx, customerTransactionID, amount, arqc)
	if err != nil {
		log.Fatal(err)
	}

	log.Println(resp)

	g.JSON(http.StatusOK, resp)

}

func gorderId() string {
	b := make([]byte, 16)
	_, err := rand.Read(b)
	if err != nil {
		panic(err)
	}

	return hex.EncodeToString(b)
}

func Capture(g *gin.Context) {
	client := unigate.NewClient("", "EF09625335", "MAG888811829", "86keSz-CrA2EDMegaD_4")

	ctx := context.Background()

	MagTranID := ""

	//如果金额不足，追加授权。
	resp, err := client.IncrementalAuthorize(ctx, unigate.ReferenceAmountRequest{
		ReferenceMagTranID: MagTranID, // 引用交易ID
		Amount:             100.00,
	})
	if err != nil {
		log.Fatal(err)
	}

	//扣款
	resp, err = client.Capture(ctx, unigate.ReferenceAmountRequest{
		ReferenceMagTranID: resp.MagTranID,
		Amount:             20.00,
	})
}
